<template>
  <div class="v3-workout-result v3-screen" :data-result-stage="stage" :data-rpe-state="rpe===null?'unreported':'reported'">
    <sf-page-layout :title="stage==='complete'?'Workout complete':stage==='effort'?'Your effort':'Workout Data'" :back="stage!=='complete'" :glass="false" @back="back">
      <template #trailing><button v-if="stage!=='summary'" type="button" class="recap-header-link" @click="navigate('summary')">View summary</button><button v-else type="button" class="sf-icon-button" aria-label="Share workout" @click="openShare"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 15V3m-4 4 4-4 4 4M5 12v7a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-7"/></svg></button></template>
      <div v-if="stage!=='summary'" class="recap-progress" aria-label="Workout recap progress"><span v-for="(step,index) in ['complete','effort','summary']" :key="step" :class="{'is-complete':index<stageIndex,'is-current':step===stage}"/><small>{{ stageIndex+1 }} / 3</small></div>

      <section v-if="stage==='complete'" class="recap-completion">
        <div class="recap-completion__art"><result-award v-if="achievement"/><span v-else class="recap-completion__check"><sf-icon name="check" :size="48"/></span></div>
        <p class="recap-eyebrow" :class="{'recap-eyebrow--record':achievement}">{{ achievement?(achievement.kind==='milestone'?'MILESTONE':'PERSONAL BEST'):'SESSION COMPLETE' }}</p>
        <h1 tabindex="-1">{{ achievement?achievement.title:'Ride complete.' }}</h1>
        <div class="recap-completion__value"><strong>{{ achievement?achievement.value:workout.distance }}</strong><span>{{ achievement?achievement.unit:workout.distanceUnit }}</span></div>
        <p v-if="achievement&&achievement.previous" class="recap-comparison"><span>{{ achievement.improvement }}</span> · Previous best {{ achievement.previous }}</p>
        <p v-else-if="achievement" class="recap-comparison">One ride at a time.</p>
        <p v-else class="recap-comparison">Another ride, in the books.</p>
        <div class="recap-session"><strong>{{ workout.title }}</strong><span>{{ workout.dateLabel }}</span></div>
        <div class="recap-completion-stats" :style="{gridTemplateColumns:'repeat('+completionMetrics.length+',minmax(0,1fr))'}"><div v-for="metric in completionMetrics" :key="metric.label"><span>{{ metric.label }}</span><strong>{{ metric.value }}<small v-if="metric.unit">{{ metric.unit }}</small></strong></div></div>
      </section>

      <section v-else-if="stage==='effort'" class="recap-effort">
        <p class="recap-eyebrow">CHECK IN WITH YOURSELF</p><h1 tabindex="-1">How did that feel?</h1><p class="recap-effort__intro">Rate the effort of your whole workout.</p>
        <div class="recap-effort__context"><sf-icon name="calendar" :size="14"/>{{ workout.title }} · {{ workout.duration }}</div>
        <div class="recap-effort__value" aria-live="polite"><strong>{{ selection===null?'—':selection }}</strong><span>{{ selection===null?'Choose your effort':effortLabel(selection) }}</span></div>
        <div class="workout-rpe-options" role="radiogroup" aria-label="Perceived effort from 1 to 10"><button v-for="n in 10" :key="n" type="button" role="radio" :aria-checked="selection===n?'true':'false'" :aria-label="'RPE '+n+' · '+effortLabel(n)" :tabindex="selection===n||selection===null&&n===1?0:-1" @click="selection=n" @keydown="navigateRpe($event,n)">{{ n }}</button></div>
        <div class="workout-rpe-scale"><span>Very easy</span><span>Maximum effort</span></div>
      </section>

      <section v-else class="recap-summary">
        <div class="recap-summary__identity"><h1 tabindex="-1">{{ workout.title }}</h1><p>{{ workout.dateLabel }}</p></div>
        <sf-card class="recap-summary-stats"><div v-for="metric in workout.metrics" :key="metric.label"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.unit||'min : sec' }}</small></div></sf-card>
        <div v-if="achievement" class="recap-record-line"><sf-icon name="spark" :size="18"/><strong>{{ achievement.title }}</strong><span>{{ achievement.kind==='milestone'?'Milestone':'New best' }}</span></div>
        <div v-if="rpe!==null" class="workout-rpe-saved"><div><span>Your effort</span><strong>RPE {{ rpe }} <small>/ 10 · {{ effortLabel(rpe) }}</small></strong></div><button type="button" aria-label="Edit RPE" @click="navigate('effort')">Edit</button></div>
        <button v-else type="button" aria-label="Report RPE" class="recap-rpe-later" @click="navigate('effort')"><div><strong>How did it feel?</strong><span>Add your effort to this workout</span></div><span>Report RPE <sf-icon name="arrow" :size="14"/></span></button>
        <template v-if="rpe!==null">
          <sf-insight-card v-if="hasInsight||loading" class="result-insight" :rpe="rpe" :saved="hasInsight&&!loading" :body="body" :busy="loading" :state="loading?'insight-loading':'saved-insight'" @ask="$emit('action','coach-workout')"/>
          <sf-card v-else class="workout-insight-entry"><div class="recap-insight-heading"><img :src="asset('restored/orbs/insight.png')" width="30" height="30" alt=""/><h2>AI Coach Insight</h2><sf-badge>Premium</sf-badge></div><p>See your ride and your effort together, with a personal workout recap.</p><sf-button appearance="glass" @click="$emit('action','generate-insight')">Get workout analysis</sf-button></sf-card>
        </template>
        <section class="recap-detail-section"><button type="button" class="recap-details-toggle" :aria-expanded="detailsOpen?'true':'false'" aria-controls="workout-details" @click="toggleDetails"><strong>Workout details</strong><span>{{ detailsOpen?'Hide':'View' }}<sf-icon :name="detailsOpen?'minus':'plus'" :size="16"/></span></button>
          <div v-if="detailsOpen" id="workout-details" class="workout-result-data">
            <sf-card class="workout-heart-rate"><div class="workout-heart-rate__heading"><h2><sf-icon name="heart-pulse" :size="17"/>Heart rate</h2><div><span>Avg <strong>{{ workout.avgHeartRate }}</strong></span><span>Max <strong>{{ workout.maxHeartRate }}</strong></span><small>BPM</small></div></div><svg viewBox="0 0 300 122" role="img" :aria-label="'Heart rate throughout the workout, average '+workout.avgHeartRate+' and maximum '+workout.maxHeartRate+' beats per minute'"><defs><linearGradient id="recap-heart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ff5d63" stop-opacity=".2"/><stop offset="1" stop-color="#ff5d63" stop-opacity="0"/></linearGradient></defs><path d="M0 26H300M0 62H300M0 98H300" stroke="currentColor" opacity=".1" stroke-dasharray="3 4"/><path :d="heartLine+' L300 122H0Z'" fill="url(#recap-heart-fill)"/><path :d="heartLine" fill="none" stroke="#fb4e55" stroke-width="1.7" stroke-linecap="round"/></svg><div class="recap-chart-axis"><span>0:00</span><span>20:00</span><span>{{ workout.duration }}</span></div></sf-card>
            <sf-card title="Heart rate zones" class="workout-heart-zones"><div v-for="zone in workout.zones" :key="zone.label"><span>{{ zone.label }}</span><i><b :style="{width:zone.value+'%',background:zone.color}"/></i><strong>{{ zone.value }}%</strong></div></sf-card>
            <sf-card class="recap-extra-stats"><div><span>Avg speed</span><strong>{{ workout.avgSpeed }} <small>mph</small></strong></div><div><span>Avg power</span><strong>{{ workout.avgPower }} <small>W</small></strong></div></sf-card>
          </div>
        </section>
      </section>
      <template #footer>
        <template v-if="stage==='complete'"><sf-button @click="navigate('effort')">Continue</sf-button><button type="button" class="recap-secondary-action" @click="openShare">{{ achievement?'Share achievement':'Share workout' }}</button></template>
        <template v-else-if="stage==='effort'"><sf-button :disabled="selection===null" @click="submitRpe">Save RPE &amp; continue</sf-button><button type="button" class="recap-secondary-action" @click="navigate('summary')">Skip for now</button></template>
        <sf-button v-else @click="$emit('action','home')">Done</sf-button>
      </template>
    </sf-page-layout>
    <sf-sheet v-model="shareOpen" title="Share your workout" contained :resizable="false"><div class="recap-share-preview"><img v-if="shareCard" :src="shareCard.url" alt="SunnyFit share card with workout stats and achievements"/><div v-else class="recap-share-preparing" role="status">Preparing your card…</div></div><template #footer><sf-button :disabled="!shareCard||sharing" @click="share">{{ sharing?'Sharing…':nativeSharing?'Share':'Save image' }}</sf-button><button v-if="nativeSharing" type="button" class="recap-secondary-action" @click="saveImage">Save image</button></template></sf-sheet>
    <sf-toast v-model="noticeOpen" :message="notice"/>
  </div>
</template>
<script>
import {SfPageLayout,SfCard,SfButton,SfIcon,SfSheet,SfBadge,SfInsightCard,SfToast} from '@/design-system'
import ResultAward from './ResultAward'
import {createWorkoutShareCard,downloadWorkoutCard,canShareWorkoutCard} from './share-workout'
const efforts=['Very easy','Easy','Light','Moderate','Somewhat hard','Hard','Very hard','Very hard','Extremely hard','Maximum effort']
const stages=['complete','effort','summary']
export default {
  components:{SfPageLayout,SfCard,SfButton,SfIcon,SfSheet,SfBadge,SfInsightCard,SfToast,ResultAward},
  props:{workout:{type:Object,required:true},rpe:{type:Number,default:null},hasInsight:Boolean,loading:Boolean,body:String,reviewStage:String,reviewPanel:String},
  data(){return {stage:stages.includes(this.reviewStage)?this.reviewStage:this.rpe===null?'complete':'summary',selection:this.rpe,effortOrigin:'complete',detailsOpen:this.reviewPanel==='details',shareOpen:false,shareCard:null,sharing:false,notice:'',noticeOpen:false,shareVersion:0}},
  computed:{completionMetrics(){return this.achievement?.kind==='milestone'?this.workout.metrics:this.workout.metrics.filter(metric=>metric.label!=='Distance')},achievement(){return this.workout.achievements[0]||null},stageIndex(){return stages.indexOf(this.stage)},heartLine(){const values=this.workout.heartRate;return values.map((n,i)=>(i?'L':'M')+(i/(values.length-1)*300).toFixed(1)+' '+(110-(n-75)/90*95).toFixed(1)).join(' ')},nativeSharing(){return canShareWorkoutCard(this.shareCard)}},
  watch:{reviewStage(value){if(stages.includes(value)){this.stage=value;if(value==='effort')this.selection=this.rpe}},reviewPanel(value){this.detailsOpen=value==='details'},rpe(value){this.selection=value},workout(){this.shareVersion++;if(this.shareCard)URL.revokeObjectURL(this.shareCard.url);this.shareCard=null;this.shareOpen=false}},
  beforeDestroy(){this.shareVersion++;if(this.shareCard)URL.revokeObjectURL(this.shareCard.url)},
  methods:{
    asset(path){return process.env.BASE_URL+'assets/figma/'+path},effortLabel(n){return efforts[n-1]},
    navigate(stage){if(stage==='effort'){this.effortOrigin=this.stage==='summary'?'summary':'complete';this.selection=this.rpe}this.stage=stage;this.$emit('stage-change',stage);this.$nextTick(()=>{this.$el.querySelector('.sf-page-layout__scroll')?.scrollTo(0,0);this.$el.querySelector('h1')?.focus({preventScroll:true})})},
    back(){if(this.stage==='effort')this.navigate(this.effortOrigin);else this.$emit('action','back')},
    submitRpe(){if(this.selection===null)return;this.$emit('submit-rpe',this.selection);this.stage='summary'},
    toggleDetails(){this.detailsOpen=!this.detailsOpen;this.$emit('panel-change',this.detailsOpen?'details':'overview')},
    navigateRpe(event,n){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();this.selection=event.key==='Home'?1:event.key==='End'?10:Math.min(10,Math.max(1,n+(event.key==='ArrowRight'?1:-1)));this.$nextTick(()=>this.$el.querySelectorAll('.workout-rpe-options button')[this.selection-1].focus())},
    async openShare(){this.shareOpen=true;if(this.shareCard)return;const version=++this.shareVersion;try{const card=await createWorkoutShareCard(this.workout);if(version!==this.shareVersion){URL.revokeObjectURL(card.url);return}this.shareCard=card}catch(_){this.shareOpen=false;this.notify('Please try sharing again.')}},
    async share(){if(!this.shareCard||this.sharing)return;if(!this.nativeSharing){this.saveImage();return}this.sharing=true;try{await navigator.share({title:this.achievement?this.achievement.title:'My SunnyFit workout',files:[this.shareCard.file]});this.notify('Shared')}catch(error){if(error.name!=='AbortError')this.notify('You can save the image to share it.')}finally{this.sharing=false}},
    saveImage(){if(!this.shareCard)return;downloadWorkoutCard(this.shareCard);this.notify('Share card downloaded')},notify(text){this.notice=text;this.noticeOpen=true}
  }
}
</script>
