:10px;color:var(--sf-text-secondary)}.recap-rpe-later>span{display:flex;gap:1px;align-items:center;font-size:11px;color:var(--sf-action);white-space:nowrap}.result-insight{position:static;inset:auto;width:auto;height:auto;border-radius:18px!important;padding:16px!important;min-height:0!important}.workout-insight-entry{padding:16px;border-radius:18px;display:grid;gap:12px}.recap-insight-heading{display:flex;align-items:center;gap:7px}.recap-insight-heading h2{font-size:14px;margin:0;line-height:22px;font-weight:600}.recap-insight-heading .sf-badge{margin-left:auto;font-size:9px}.workout-insight-entry p{margin:0;font-size:13px;line-height:21px;color:var(--sf-text-secondary)}.workout-insight-entry .sf-button{font-size:13px;min-height:44px;color:var(--sf-action)}.result-insight::v-deep .sf-insight-card__body{font-size:14px;line-height:22px}.recap-details-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:52px;border:0;border-top:1px solid var(--sf-content-edge);background:transparent;padding:8px 2px;font:400 13px var(--sf-font-family);color:var(--sf-text);cursor:pointer}.recap-details-toggle strong{font-weight:600}.recap-details-toggle>span{display:flex;align-items:center;gap:8px;color:var(--sf-text-secondary);font-size:11px}.workout-result-data{display:grid;gap:14px;margin-top:8px}.workout-result-data .sf-card{padding:16px}.workout-heart-rate__heading{display:flex;justify-content:space-between;align-items:center;gap:8px}.workout-heart-rate h2{display:flex;align-items:center;gap:6px;margin:0;font-size:13px;font-weight:600}.workout-heart-rate h2 .sf-icon{color:var(--sf-action)}.workout-heart-rate__heading>div{display:flex;align-items:baseline;gap:9px}.workout-heart-rate__heading span{display:grid;font-size:9px;color:var(--sf-text-secondary)}.workout-heart-rate__heading strong{font-size:17px;color:var(--sf-text);font-weight:600}.workout-heart-rate__heading small{font-size:9px;color:var(--sf-chevron)}.workout-heart-rate>svg{width:100%;display:block;margin-top:18px}.recap-chart-axis{display:flex;justify-content:space-between;font-size:9px;color:var(--sf-chevron);margin-top:5px}.workout-heart-zones>div{display:flex;gap:10px;align-items:center;margin:16px 0;font-size:11px}.workout-heart-zones i{flex:1;height:5px;background:var(--sf-content-edge);border-radius:5px;overflow:hidden}.workout-heart-zones b{display:block;height:100%;border-radius:5px}.workout-heart-zones strong{min-width:30px;text-align:right;font-weight:500}.recap-extra-stats{display:grid;grid-template-columns:1fr 1fr;gap:14px}.recap-extra-stats>div{display:grid;gap:8px}.recap-extra-stats span{font-size:11px;color:var(--sf-text-secondary)}.recap-extra-stats strong{font-size:21px;font-weight:600}.recap-extra-stats small{font-size:10px;font-weight:400}.recap-share-preview{max-width:300px;margin:0 auto}.recap-share-preview img{display:block;width:100%;border-radius:16px;box-shadow:0 6px 22px #68728c14}.recap-share-preparing{padding:80px 10px;text-align:center;font-size:13px;color:var(--sf-text-secondary)}
@media(max-width:360px){.v3-workout-result::v-deep .sf-page-layout__content{padding-left:16px;padding-right:16px}.recap-completion h1,.recap-effort h1{font-size:25px}.recap-completion__art{height:90px;margin-bottom:10px}.recap-completion__art>.result-award{width:108px;height:99px}.recap-completion__value strong{font-size:62px;line-height:70px}.recap-session{margin-top:24px}.recap-completion-stats strong{font-size:19px}.recap-completion-stats small{font-size:9px}.recap-effort__value{margin:24px 0}.workout-rpe-options{gap:8px}}
</style>
